import { DomainError, InvalidOrderTransitionError } from "./errors";

export const orderStates = ["placed", "paid", "packed", "shipped", "delivered", "cancelled"] as const;
export type OrderState = (typeof orderStates)[number];

export interface OrderItem {
  readonly productId: string;
  readonly quantity: number;
}

const nextState: Readonly<Record<Exclude<OrderState, "cancelled">, OrderState | undefined>> = {
  placed: "paid",
  paid: "packed",
  packed: "shipped",
  shipped: "delivered",
  delivered: undefined,
};

export class Order {
  private currentState: OrderState = "placed";

  public constructor(
    public readonly id: string,
    public readonly items: readonly OrderItem[],
  ) {
    if (!id.trim()) throw new DomainError("Order id is required");
    if (items.length === 0) throw new DomainError("An order requires at least one item");
    for (const item of items) {
      if (!item.productId.trim() || !Number.isInteger(item.quantity) || item.quantity <= 0) {
        throw new DomainError("Each order item needs a product id and positive integer quantity");
      }
    }
  }

  public get state(): OrderState {
    return this.currentState;
  }

  public advanceTo(target: Exclude<OrderState, "placed" | "cancelled">): void {
    if (nextState[this.currentState as Exclude<OrderState, "cancelled">] !== target) {
      throw new InvalidOrderTransitionError(`Order cannot move from ${this.currentState} to ${target}`);
    }
    this.currentState = target;
  }

  public cancel(): void {
    if (this.currentState === "cancelled") {
      throw new InvalidOrderTransitionError("Order is already cancelled");
    }
    if (this.currentState === "shipped" || this.currentState === "delivered") {
      throw new InvalidOrderTransitionError("A shipped order cannot be cancelled");
    }
    this.currentState = "cancelled";
  }
}

