import { DomainError, InsufficientStockError } from "./errors";

export class Product {
  public constructor(
    public readonly id: string,
    public readonly name: string,
    private availableStock: number,
  ) {
    if (!id.trim() || !name.trim()) throw new DomainError("Product id and name are required");
    if (!Number.isInteger(availableStock) || availableStock < 0) {
      throw new DomainError("Stock must be a non-negative integer");
    }
  }

  public get stock(): number {
    return this.availableStock;
  }

  public reserve(quantity: number): void {
    this.assertQuantity(quantity);
    if (quantity > this.availableStock) {
      throw new InsufficientStockError(`Insufficient stock for product ${this.id}`);
    }
    this.availableStock -= quantity;
  }

  public release(quantity: number): void {
    this.assertQuantity(quantity);
    this.availableStock += quantity;
  }

  private assertQuantity(quantity: number): void {
    if (!Number.isInteger(quantity) || quantity <= 0) {
      throw new DomainError("Quantity must be a positive integer");
    }
  }
}

